const ids = ["ORD-1", "ORD-1", "ORD-2", "ORD-5", "ORD-5", "ORD-9"];

function dedupeSorted(list) {
  if (list.length === 0) return 0;
  let write = 1;
  for (let read = 1; read < list.length; read++) {
    if (list[read] !== list[write - 1]) {
      list[write] = list[read];
      write++;
    }
  }
  list.length = write;
  return write;
}

const kept = dedupeSorted(ids);
console.log(kept, ids);

