function isMirror(name) {
  const s = name.toLowerCase();
  const ok = (ch) => /[a-z0-9]/.test(ch);
  let left = 0;
  let right = s.length - 1;
  while (left < right) {
    if (!ok(s[left])) left++;
    else if (!ok(s[right])) right--;
    else if (s[left] !== s[right]) return false;
    else {
      left++;
      right--;
    }
  }
  return true;
}

console.log(isMirror("Ada.D.a"), isMirror("bola_1"));

