function packTotals(list) {
  let write = 0;
  for (let read = 0; read < list.length; read++) {
    if (list[read] !== 0) {
      list[write] = list[read];
      write++;
    }
  }
  for (let i = write; i < list.length; i++) list[i] = 0;
}

packTotals(totals);
